export interface MachoteResumen {
  id: number;
  version: number;
  aprobado: boolean | null;
  sentido: string | null;
  motivo: string | null;
  createdAt: string;
}

export function machoteBadgeTexto(
  machote: MachoteResumen | null | undefined,
): string {
  if (!machote) return 'Sin machote';
  if (!machote.aprobado) return 'En revisión';
  if (machote.sentido === 'Autorizada') return 'Aprobado';
  if (machote.sentido === 'No Autorizada') return 'Requiere corrección';
  return 'Revisado';
}

export function machoteBadgeClass(
  machote: MachoteResumen | null | undefined,
): string {
  if (!machote) return 'bg-secondary';
  if (!machote.aprobado) return 'bg-warning text-dark';
  if (machote.sentido === 'Autorizada') return 'bg-success';
  if (machote.sentido === 'No Autorizada') return 'bg-danger';
  return 'bg-secondary';
}
